# Siri and Shortcuts phrases ("${applicationName}" is the app's name).
APP_SHORTCUTS = {
    "What should I open tonight in ${applicationName}": "Que boire ce soir avec ${applicationName}",
    "What to drink tonight with ${applicationName}": "Quoi ouvrir ce soir avec ${applicationName}",
    "Where is ${wine} in ${applicationName}": "Où est ${wine} dans ${applicationName}",
    "Find ${wine} in ${applicationName}": "Trouver ${wine} dans ${applicationName}",
    "What should I drink soon in ${applicationName}": "Quoi boire bientôt avec ${applicationName}",
    "Add a bottle to ${applicationName}": "Ajouter une bouteille à ${applicationName}",
    "Scan a wine label with ${applicationName}": "Scanner une étiquette avec ${applicationName}",
    "Ask my cellar in ${applicationName}": "Demander à ma cave dans ${applicationName}",
    "Ask my cellar with ${applicationName}": "Demander à ma cave avec ${applicationName}",
}

# Not preceded by a letter, so identifiers such as "devices.joinButton" are not read as Button("…").
UI_CALL = re.compile(r'(?<![A-Za-z0-9_])(?:Text|Label|Button|Section|LabeledContent|navigationTitle|Toggle|TextField|Picker|Stepper|'
                     r'DisclosureGroup|SecureField|LabeledField|ActionLabel|fieldHelp|title:|body:|summary:|ContentUnavailableView|Tab|ChoiceChip\(title:|RackPreset\(title:|caption:|ChartCard\(title:|DatePicker|'
                     r'String\(localized:|alert|confirmationDialog|Link|prompt: Text|LocalizedStringResource =|TypeDisplayRepresentation =|'
                     r'IntentDescription|dialog:|shortTitle:|TableColumn|footer:|header:|configurationDisplayName|displayName|description)\s*\(?\s*"((?:[^"\\]|\\.)*)"')
CASE_STRING = re.compile(r'case \.[a-zA-Z]+: "((?:[^"\\]|\\.)*)"')


def unit(value):
    return {"stringUnit": {"state": "translated", "value": value}}


# French typography: a narrow no-break space before ? ! ; and inside « », and a no-break
# space before :, so the mark never starts or ends a line. URLs and format specifiers are
# left as they are.
NARROW_NBSP, NBSP = "\u202f", "\u00a0"
VERBATIM = re.compile(r"(https?://\S+|%(?:\d+\$)?[-+ #0]*\d*(?:\.\d+)?(?:lld|ld|d|@|lf|f|s))")
LOOSE_FRENCH_MARK = re.compile(r"[ \u00a0\u202f]+([?!;:])")
LOOSE_GUILLEMETS = (re.compile(r"«[ \u00a0\u202f]*"), re.compile(r"[ \u00a0\u202f]*»"))


def french(text):
    parts = VERBATIM.split(text)
    for i in range(0, len(parts), 2):
        parts[i] = LOOSE_FRENCH_MARK.sub(lambda m: (NBSP if m.group(1) == ":" else NARROW_NBSP) + m.group(1), parts[i])
        parts[i] = LOOSE_GUILLEMETS[0].sub("«" + NARROW_NBSP, parts[i])
        parts[i] = LOOSE_GUILLEMETS[1].sub(NARROW_NBSP + "»", parts[i])
    return "".join(parts)


def loose_guillemets(text):
    """« or » without a narrow no-break space inside."""
    return re.findall(r"«(?!\u202f)\S{0,12}|\S{0,12}(?<!\u202f)»", text)


HELP = ROOT / "Encave" / "Features" / "Help" / "HelpContent.swift"
# Bold words of the help that are not text of the app: services named in CaveKit, file
# names and examples.
HELP_NAMES = {"8/10", "Brave Search", "Tavily", "README.txt", "files.json"}
LITERAL = re.compile(r'"((?:[^"\\\n]|\\.)*)"')
FORMAT = re.compile(r"%(?:\d+\$)?(?:lld|ld|d|@|lf|f)")


def help_words_missing():
    """The bold words of the help bodies (each step of "Settings › Your data") that the rest
    of the app never shows, in English and in French: a button, setting or screen that was
    renamed or removed. Position names such as "Shelf 2, position 3" match their pattern."""
    literals = set()
    for path in glob.glob(str(ROOT / "Encave" / "**" / "*.swift"), recursive=True):
        if Path(path) != HELP:
            literals.update(to_key(k) for k in LITERAL.findall(Path(path).read_text()))
    english = sorted(literals)
    french_texts = sorted({FR[k] for k in literals if k in FR} | {f for k in literals if k in PLURALS for f in PLURALS[k][1]}
                          | literals)
    bodies = LITERAL.findall("\n".join(re.findall(r'body: "(?:[^"\\]|\\.)*"', HELP.read_text())))
    missing = []
    for lang, texts, helps in (("English", english, bodies), ("French", french_texts, [FR.get(b, "") for b in bodies])):
        joined = "\n".join(texts)
        patterns = [re.compile(r"(?:\d+|.+?)".join(re.escape(p) for p in FORMAT.split(t)), re.I)
                    for t in texts if FORMAT.search(t) and len(re.findall(r"[^\W\d_]", FORMAT.sub("", t))) >= 4]
        for text in helps:
            for term in re.findall(r"\*\*(.+?)\*\*", text):
                for word in (w.strip().rstrip("…") for w in term.split(" › ")):
                    whole = re.compile(r"(?<!\w)" + re.escape(word) + r"(?!\w)", re.I)
                    if word in HELP_NAMES or whole.search(joined) or any(p.fullmatch(word) for p in patterns):
                        continue
                    missing.append((lang, word))
    return missing


def plain_space_before_mark(text):
    """The marks still preceded by a plain space, outside URLs and format specifiers."""
    return [m.group(0) for i, part in enumerate(VERBATIM.split(text)) if i % 2 == 0
            for m in re.finditer(r"\S{0,12} [?!;:]", part)]


def to_key(literal):
    """Swift interpolation → format key ("\\(count) bottles" → "%lld bottles")."""
    def repl(match):
        expr = match.group(1)
        if "count" in expr or any(op in expr for op in (" - ", " + ", " * ", "reduce")):
            return "%lld"
        stringy = any(t in expr for t in ("name", "Name", "label", "Label", "first", "formatted", "location", "displayName",
                                            "letters", "Letters", "place", "digits"))
        return "%@" if stringy else "%lld"
    return re.sub(r"\\\((.*?)\)(?=[^)]*(?:\\\(|$))", repl, literal) if "\\(" in literal else literal


def extract(paths=None):
    keys = set()
    for path in paths if paths is not None else app_sources():
        source = Path(path).read_text()
        keys.update(UI_CALL.findall(source))
        if "LocalizedStringKey" in source:
            keys.update(CASE_STRING.findall(source))
        for block in re.findall(r"caseDisplayRepresentations: \[\w+: DisplayRepresentation\] = \[(.*?)\n    \]", source, re.S):
            keys.update(re.findall(r'\.\w+: "((?:[^"\\]|\\.)*)"', block))
        for block in re.findall(r"\[LocalizedStringResource\] = \[(.*?)\]", source, re.S):
            keys.update(re.findall(r'"([^"]+)"', block))
        keys.update(re.findall(r'\("((?:[^"\\]|\\.)*)", \d+, \d+, \.(?:grid|diamond)\)', source))
    # Skip SF Symbol names and other identifiers.
    return {k for k in keys if k.strip() and not re.fullmatch(r"[a-z0-9.]+", k)}


def catalogs():
    """The catalog files, as written: {path: text}."""
    strings = {key: {"localizations": {"fr": unit(french(value))}} for key, value in FR.items() if key.strip() == key}
    for name, ((en_one, en_other), (fr_one, fr_other)) in CAPTIONS.items():
        for form, en, fr in (("one", en_one, fr_one), ("other", en_other, fr_other)):
            strings[f"{name} [{form}]"] = {"localizations": {"en": unit(en), "fr": unit(french(fr))}}
    for key, (en, fr) in VARIANTS.items():
        strings[key] = {"localizations": {"en": unit(en), "fr": unit(french(fr))}}
    for key, ((en_one, en_other), (fr_one, fr_other)) in PLURALS.items():
        strings[key] = {"localizations": {
            "en": {"variations": {"plural": {"one": unit(en_one), "other": unit(en_other)}}},
            "fr": {"variations": {"plural": {"one": unit(french(fr_one)), "other": unit(french(fr_other))}}},
        }}
    catalog = {"sourceLanguage": "en", "strings": dict(sorted(strings.items())), "version": "1.0"}
    # The widget extension's catalog: the same translations, for the keys its sources use.
    used = extract(widget_sources())
    used |= {to_key(k) for k in used}
    widgets = {"sourceLanguage": "en", "strings": {k: v for k, v in catalog["strings"].items() if k in used}, "version": "1.0"}
    info = {key: {"localizations": {"en": unit(en), "fr": unit(french(fr))}} for key, (en, fr) in INFO_PLIST.items()}
    shortcuts = {key: {"localizations": {"fr": unit(french(value))}} for key, value in APP_SHORTCUTS.items()}

    def text(value):
        return json.dumps(value, indent=2, ensure_ascii=False) + "\n"
    return {
        RES / "Localizable.xcstrings": text(catalog),
        RES / "InfoPlist.xcstrings": text({"sourceLanguage": "en", "strings": info, "version": "1.0"}),
        RES / "AppShortcuts.xcstrings": text({"sourceLanguage": "en", "strings": shortcuts, "version": "1.0"}),
        WIDGETS_RES / "Localizable.xcstrings": text(widgets),
    }


def write():
    files = catalogs()
    for path, text in files.items():
        path.write_text(text)
    count = len(json.loads(files[RES / "Localizable.xcstrings"])["strings"])
    print(f"Wrote {count} strings")


PLACEHOLDER = re.compile(r"%(?:\d+\$)?(?:lld|ld|d|@|lf|f)")


def placeholders(text):
    """Format placeholders without their positions: "%1$@ %2$lld" -> ["%@", "%lld"]."""
    return sorted(re.sub(r"\d+\$", "", p) for p in PLACEHOLDER.findall(text))


# The words the lexicon replaced (CHANGELOG, "Racks are now Storage"): a position is a
# "position", never an "emplacement" or a "place"; a fridge is a "cave à vin réfrigérée",
# as "cave" alone is the whole collection.
OLD_FRENCH = (
    (re.compile(r"\bemplacements?\b", re.I), "“emplacement” (say “position” or “rangement”)"),
    (re.compile(r"(?<!à )(?<!de )\b(?:une|la|les|des|cette|chaque|aucune|nouvelle|sa|ses|leur|leurs|par)\s+places?\b"
                r"|\bplaces?\s+(?:libres?|\d|%)", re.I), "“place” for a position (say “position”)"),
    (re.compile(r"\bcaves? à vin\b(?! réfrigérée)", re.I), "“cave à vin” for a fridge (say “cave à vin réfrigérée”)"),
)


def old_french_words(text):
    return [why for pattern, why in OLD_FRENCH if pattern.search(text)]


def check():
    known = set(FR) | set(PLURALS) | set(VARIANTS)
    problems = []
    for key in sorted(k for k in extract() | extract(widget_sources()) if to_key(k) not in known and k not in known):
        problems.append(f"missing French: {key!r} (key {to_key(key)!r})")
    # A translation must use the same placeholders as its key, or it shows the wrong value or crashes.
    for key, value in FR.items():
        if placeholders(key) != placeholders(value):
            problems.append(f"placeholders differ: {key!r} -> {value!r}")
    for key, forms in PLURALS.items():
        for form in forms[0] + forms[1]:
            if placeholders(form) != placeholders(key):
                problems.append(f"placeholders differ in a plural form: {key!r} -> {form!r}")
    for key, forms in VARIANTS.items():
        if any(placeholders(form) != placeholders(key) for form in forms):
            problems.append(f"placeholders differ in a variant: {key!r}")
    for name, forms in CAPTIONS.items():
        if placeholders(name) or any(placeholders(form) for form in forms[0] + forms[1]):
            problems.append(f"a caption holds no number: {name!r}")
    # Captions used in the app ("caption: .count(\"bottles\", ...)") must be in CAPTIONS.
    for path in glob.glob(str(ROOT / "Encave" / "**" / "*.swift"), recursive=True):
        for name in re.findall(r'\.count\("((?:[^"\\]|\\.)*)", ', Path(path).read_text()):
            if name not in CAPTIONS:
                problems.append(f"caption not in CAPTIONS: {name!r}")
    for key, value in list(FR.items()) + [(k, f) for k, forms in PLURALS.items() for f in forms[1]]:
        for why in old_french_words(value):
            problems.append(f"old word in French: {why}: {value[:60]!r} (key {key[:40]!r})")
    # Keys with spaces around them are dropped from the catalog: the text would stay in English.
    for key in FR:
        if key.strip() != key:
            problems.append(f"key with leading or trailing spaces is not written: {key!r}")
    # French typography: no plain space before ? ! ; or : in any written French text.
    for path, text in catalogs().items():
        for key, entry in json.loads(text)["strings"].items():
            fr = entry["localizations"].get("fr", {})
            units = [fr] if "stringUnit" in fr else list(fr.get("variations", {}).get("plural", {}).values())
            for value in (u["stringUnit"]["value"] for u in units):
                for found in plain_space_before_mark(value):
                    problems.append(f"{path.name}: plain space before a mark in French: {found!r} (key {key!r})")
                for found in loose_guillemets(value):
                    problems.append(f"{path.name}: « » without a narrow no-break space inside: {found!r} (key {key!r})")
    # Help: every body translated, and its bold words (buttons, settings, screens) shown
    # elsewhere in the app, in English and in French.
    for body in re.findall(r'body: "((?:[^"\\]|\\.)*)"', HELP.read_text()):
        if FR.get(body) == body and len(body) > 20:
            problems.append(f"help text not translated: {body[:60]!r}")
    for lang, word in help_words_missing():
        problems.append(f"help names something the app does not show in {lang}: {word!r}")
    # The committed catalogs must be the ones this script writes.
    for path, text in catalogs().items():
        if not path.exists() or path.read_text() != text:
            problems.append(f"{path.name} is not up to date: run python3 apple/tools/l10n.py")
    for problem in problems:
        print(problem)
    return 1 if problems else 0


if __name__ == "__main__":
    if "--check" in sys.argv:
        sys.exit(check())
    write()
